$ErrorActionPreference = 'Stop'
$Root = (Get-Location).Path
Write-Host 'Applying SereinOS cleanup...'
Get-ChildItem -Path $Root -Directory -Force -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -in @('__pycache__','.pytest_cache','.mypy_cache','.ruff_cache') } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $Root -Directory -Force -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '*.egg-info' } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
@('test_context.py','test_classifier.py','test_memory_extractor.py','test_nvidia.py') | ForEach-Object { Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path $Root $_) }
$oldPerf = Join-Path $Root 'serein-core\serein_core\performance'
$newPerf = Join-Path $Root 'serein-core\src\serein_core\performance'
if (Test-Path $oldPerf) { New-Item -ItemType Directory -Force $newPerf | Out-Null; Copy-Item (Join-Path $oldPerf '*') $newPerf -Force; Remove-Item $oldPerf -Recurse -Force }
if (Test-Path (Join-Path $Root 'serein-core\serein_core')) { Remove-Item (Join-Path $Root 'serein-core\serein_core') -Recurse -Force }
$path = Join-Path $Root '.gitignore'
New-Item -ItemType Directory -Force (Split-Path $path) | Out-Null
